package com.wizzadrds.theworldremembers.dream; import com.wizzadrds.theworldremembers.memory.*; import java.util.*; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*; class DreamGeneratorTest{@Test void generationIsDeterministic(){UUID id=UUID.randomUUID();var m=new Memory(id,new UUID(0,1),MemoryEventType.NPC_DIED,10,MemoryImportance.IMPORTANT);var a=DreamGenerator.generate(id,List.of(m),0,24000).orElseThrow();var b=DreamGenerator.generate(id,List.of(m),0,24000).orElseThrow();assertEquals(a,b);assertTrue(a.type()==DreamType.FEAR||a.type()==DreamType.MEMORY||a.type()==DreamType.IMPOSSIBLE||a.type()==DreamType.NOSTALGIA);}@Test void impossibleDreamIsMarkedNonFactual(){UUID id=UUID.randomUUID();var m=new Memory(id,new UUID(0,1),MemoryEventType.PLAYER_GAVE_BREAD,10,MemoryImportance.IMPORTANT);Dream d=DreamGenerator.generate(id,List.of(m),0,24000).orElseThrow();if(d.type()==DreamType.IMPOSSIBLE)assertFalse(d.factual());}}
